};
const cellValue = (value) => {
  if (!value) return undefined;
  if (Object.hasOwn(value, 'stringValue')) return value.stringValue;
  if (Object.hasOwn(value, 'numberValue')) return value.numberValue;
  return null; // A formula or another cell type must never match a replay.
};
const headings = readCells(0).map(cellValue);
if (!header.every((key, index) => headings[index] === key)) return respond(503, 'sheet_layout_mismatch');

const cells = readCells(rowIndex);
const values = header.map(key => event[key]);
if (cells.some(cell => cell && Object.keys(cell).length > 0)) {
  if (values.every((value, index) => cellValue(cells[index]) === value)) return respond(200, 'written');
  return respond(409, 'conflict');
}

// An empty row after an uncertain write is retriable. Never confirm it.
return respond(503, 'write_unconfirmed');
